16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "postcode")
59	    private String postcode;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    private String email;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "registration_date")
73	    private LocalDate registrationDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    /**
94	     * Whether this owner was knowingly created into a shared household (the request declared shared
95	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
96	     * never persisted.
97	     */
98	    @Transient
99	    private boolean declaredHouseholdMember;
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
103	
104	    /**
105	     * Resolve the registration date at creation time: default it to the server's
106	     * current date when none was supplied, and roll a weekend date forward to the
107	     * next business day so every value derived from it (such as the membership
108	     * number's year segment) uses the adjusted date.
109	     */
110	    @PrePersist
111	    private void resolveRegistrationDate() {
112	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
113	    }
114	
115	    public String getTitle() {
116	        return this.title;
117	    }
118	
119	    public void setTitle(String title) {
120	        this.title = title;
121	    }
122	
123	    /**
124	     * The owner's salutation: the {@link #title} followed by a space and the
125	     * {@linkplain #getLastName() last name} (e.g. {@code "DR Who"}), or just the
126	     * last name when no title is on file.
127	     */
128	    public String getSalutation() {
129	        if (this.title == null || this.title.isEmpty()) {
130	            return getLastName();
131	        }
132	        return this.title + " " + getLastName();
133	    }
134	
135	    public String getAddress() {
136	        return this.address;
137	    }
138	
139	    public void setAddress(String address) {
140	        this.address = address;
141	    }
142	
143	    public String getAddressLine1() {
144	        return this.addressLine1;
145	    }
146	
147	    public void setAddressLine1(String addressLine1) {
148	        this.addressLine1 = addressLine1;
149	    }
150	
151	    public String getAddressLine2() {
152	        return this.addressLine2;
153	    }
154	
155	    public void setAddressLine2(String addressLine2) {
156	        this.addressLine2 = addressLine2;
157	    }
158	
159	    public String getCity() {
160	        return this.city;
161	    }
162	
163	    public void setCity(String city) {
164	        this.city = city;
165	    }
166	
167	    public String getPostcode() {
168	        return this.postcode;
169	    }
170	
171	    public void setPostcode(String postcode) {
172	        this.postcode = postcode;
173	    }
174	
175	    /**
176	     * The owner's locality: the region component of its {@link #customerCode}
177	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
178	     * is assigned. The region was derived from the owner's postcode and city when
179	     * the identity was minted, so the locality now follows the identity rather than
180	     * being recomputed from the current city and postcode.
181	     */
182	    public String getLocality() {
183	        return CustomerCode.regionOf(this.customerCode);
184	    }
185	
186	    /**
187	     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
188	     * locality}, from the fixed region-to-timezone table (see
189	     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
190	     * no known timezone.
191	     */
192	    public String getTimezone() {
193	        return RegionTimezone.zoneFor(getLocality());
194	    }
195	
196	    public String getTelephone() {
197	        return this.telephone;
198	    }
199	
200	    public void setTelephone(String telephone) {
201	        this.telephone = telephone;
202	    }
203	
204	    public String getEmail() {
205	        return this.email;
206	    }
207	
208	    public void setEmail(String email) {
209	        this.email = email;
210	    }
211	
212	    public LocalDate getBirthDate() {
213	        return this.birthDate;
214	    }
215	
216	    public void setBirthDate(LocalDate birthDate) {
217	        this.birthDate = birthDate;
218	    }
219	
220	    /**
221	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
222	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
223	     */
224	    public AgeBand getAgeBand() {
225	        return AgeBand.on(this.birthDate, this.registrationDate);
226	    }
227	
228	    public LocalDate getRegistrationDate() {
229	        return this.registrationDate;
230	    }
231	
232	    public void setRegistrationDate(LocalDate registrationDate) {
233	        this.registrationDate = registrationDate;
234	    }
235	
236	    public String getCustomerCode() {
237	        return this.customerCode;
238	    }
239	
240	    public void setCustomerCode(String customerCode) {
241	        this.customerCode = customerCode;
242	    }
243	
244	    /**
245	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
246	     * where {@code YY} is the last two digits of the {@link #registrationDate}
247	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
248	     */
249	    public String getMembershipNumber() {
250	        if (this.customerCode == null || this.registrationDate == null) {
251	            return null;
252	        }
253	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
254	    }
255	
256	    /**
257	     * The Luhn check digit (0-9) computed over the digits of the
258	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
259	     */
260	    public Integer getCheckDigit() {
261	        if (this.customerCode == null) {
262	            return null;
263	        }
264	        return Luhn.checkDigit(this.customerCode);
265	    }
266	
267	    public String getHouseholdId() {
268	        return this.householdId;
269	    }
270	
271	    public void setHouseholdId(String householdId) {
272	        this.householdId = householdId;
273	    }
274	
275	    /**
276	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
277	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
278	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
279	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
280	     * when their whole identity keys are equal; because the telephone is part of the key, household
281	     * members with different telephones have different keys.
282	     */
283	    public String getIdentityKey() {
284	        return String.join("|",
285	            this.telephone == null ? "" : this.telephone,
286	            this.email == null ? "" : this.email,
287	            this.householdId == null ? "" : this.householdId);
288	    }
289	
290	    /** Tenure, in days, beyond which an owner earns the tenure membership points. */
291	    private static final long TENURE_DAYS_FOR_POINTS = 365;
292	
293	    /** Household size at or above which an owner earns the household membership points. */
294	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
295	
296	    /**
297	     * The owner's membership points, a score derived from the owner's own
298	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
299	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
300	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
301	     * or more, and gains {@code 3} when the owner's {@link #getTenureDays()
302	     * tenure} exceeds {@value #TENURE_DAYS_FOR_POINTS} days.
303	     */
304	    public Integer getMembershipPoints() {
305	        int points = 0;
306	        boolean hasEmail = this.email != null && !this.email.isEmpty();
307	        if (hasEmail) {
308	            points += 2;
309	        }
310	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
311	        if (noNamesakes) {
312	            points += 1;
313	        }
314	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
315	        if (largeHousehold) {
316	            points += 2;
317	        }
318	        Long tenureDays = getTenureDays();
319	        if (tenureDays != null && tenureDays > TENURE_DAYS_FOR_POINTS) {
320	            points += 3;
321	        }
322	        return points;
323	    }
324	
325	    /**
326	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
327	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
328	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
329	     */
330	    public Integer getMembershipLevel() {
331	        int points = getMembershipPoints();
332	        if (points <= 1) {
333	            return 1;
334	        }
335	        if (points <= 3) {
336	            return 2;
337	        }
338	        if (points <= 5) {
339	            return 3;
340	        }
341	        return 4;
342	    }
343	
344	    /**
345	     * The owner's tenure: the number of whole days from the {@link #registrationDate}
346	     * to the server's current date, or {@code null} when no registration date is on
347	     * file. Never negative for a registration date that is today or earlier.
348	     */
349	    public Long getTenureDays() {
350	        if (this.registrationDate == null) {
351	            return null;
352	        }
353	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
354	    }
355	
356	    /**
357	     * The owner's preferred contact channel, derived from the fields on file:
358	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
359	     */
360	    public String getContactPreference() {
361	        boolean hasEmail = this.email != null && !this.email.isEmpty();
362	        return hasEmail ? "EMAIL" : "PHONE";
363	    }
364	
365	    public Integer getNamesakeCount() {
366	        return this.namesakeCount;
367	    }
368	
369	    public void setNamesakeCount(Integer namesakeCount) {
370	        this.namesakeCount = namesakeCount;
371	    }
372	
373	    public Integer getHouseholdSize() {
374	        return this.householdSize;
375	    }
376	
377	    public void setHouseholdSize(Integer householdSize) {
378	        this.householdSize = householdSize;
379	    }
380	
381	    /**
382	     * Whether this owner, while not a declared household member, shares an existing owner's
383	     * last name and postcode but carries a different telephone. Determined once,
384	     * when the owner is created. A declared household member is never a suspected duplicate.
385	     */
386	    public Boolean getPossibleDuplicate() {
387	        return this.possibleDuplicate;
388	    }
389	
390	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
391	        this.possibleDuplicate = possibleDuplicate;
392	    }
393	
394	    /**
395	     * Whether this owner was knowingly created into a shared household. Such a declared member
396	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
397	     */
398	    public boolean isDeclaredHouseholdMember() {
399	        return this.declaredHouseholdMember;
400	    }
401	
402	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
403	        this.declaredHouseholdMember = declaredHouseholdMember;
404	    }
405	
406	    /**
407	     * The id of the existing owner this owner possibly duplicates, or {@code null}
408	     * when it has no such match.
409	     */
410	    public Integer getPossibleDuplicateOf() {
411	        return this.possibleDuplicateOf;
412	    }
413	
414	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
415	        this.possibleDuplicateOf = possibleDuplicateOf;
416	    }
417	
418	    protected Set<Pet> getPetsInternal() {
419	        if (this.pets == null) {
420	            this.pets = new HashSet<>();
421	        }
422	        return this.pets;
423	    }
424	
425	    protected void setPetsInternal(Set<Pet> pets) {
426	        this.pets = pets;
427	    }
428	
429	    public List<Pet> getPets() {
430	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
431	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
432	        return Collections.unmodifiableList(sortedPets);
433	    }
434	
435	    public void setPets(List<Pet> pets) {
436	        this.pets = new HashSet<>(pets);
437	    }
438	
439	    public void addPet(Pet pet) {
440	        getPetsInternal().add(pet);
441	        pet.setOwner(this);
442	    }
443	
444	    /**
445	     * Return the Pet with the given name, or null if none found for this Owner.
446	     *
447	     * @param name to test
448	     * @return true if pet name is already in use
449	     */
450	    public Pet getPet(String name) {
451	        return getPet(name, false);
452	    }
453	
454	    /**
455	     * Return the Pet with the given name, or null if none found for this Owner.
456	     *
457	     * @param name to test
458	     * @return true if pet name is already in use
459	     */
460	    public Pet getPet(String name, boolean ignoreNew) {
461	        name = name.toLowerCase();
462	        for (Pet pet : getPetsInternal()) {
463	            if (!ignoreNew || !pet.isNew()) {
464	                String compName = pet.getName();
465	                compName = compName.toLowerCase();
466	                if (compName.equals(name)) {
467	                    return pet;
468	                }
469	            }
470	        }
471	        return null;
472	    }
473	
474	    public Pet getPet(Integer petId) {
475	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
476	    }
477	
478	    @Override
479	    public String toString() {
480	        return new ToStringCreator(this)
481	
482	            .append("id", this.getId())
483	            .append("new", this.isNew())
484	            .append("lastName", this.getLastName())
485	            .append("firstName", this.getFirstName())
486	            .append("address", this.address)
487	            .append("city", this.city)
488	            .append("telephone", this.telephone)
489	            .append("email", this.email)
490	            .toString();
491	    }
492	}
