26	/**
27	 * Detects a soft (non-hard) duplicate for an owner being registered.
28	 *
29	 * <p>An owner is a possible duplicate of an existing owner when they share a last
30	 * name (compared case-insensitively, consistent with the rest of the application's
31	 * name handling) and a postcode but carry a different telephone. A matching
32	 * telephone is excluded because that is the territory of hard-duplicate detection
33	 * (see {@link Owner#getIdentityKey()}), not this softer signal.
34	 */
35	@Component
36	public class PossibleDuplicateDetector {
37	
38	    private final OwnerRepository ownerRepository;
39	
40	    public PossibleDuplicateDetector(OwnerRepository ownerRepository) {
41	        this.ownerRepository = ownerRepository;
42	    }
43	
44	    /**
45	     * Find the existing owner the given owner possibly duplicates, or {@code null}
46	     * when there is none. When several existing owners match, the one with the
